/**
 * The transcript.
 *
 * assistant-ui owns the message list, the message parts, and the branch picker;
 * this file decides what each of those looks like in the Studio. Everything it
 * renders comes from one place — `assistant/convert.ts` — so a new part type is
 * added in exactly two files.
 */

import {
  ActionBarPrimitive,
  AuiIf,
  BranchPickerPrimitive,
  ComposerPrimitive,
  MessagePrimitive,
  ThreadPrimitive,
  useAuiState,
} from "@assistant-ui/react";

import { formatFileSize, preparedAttachmentById } from "../../assistant/attachments";
import { SURFACE_PART } from "../../assistant/convert";
import {
  AssistantAvatar,
  FilePart,
  ReasoningPart,
  SourcePart,
  SurfacePart,
  TextPart,
  ToolPart,
  TypingPart,
} from "../../assistant/parts";
import { useStudio } from "../../state/StudioContext";
import type { StudioError } from "../../types";
import { UiActionContext } from "../../ui/actions";
import { FailurePanel } from "../FailurePanel";
import { CheckIcon, CopyIcon } from "../icons";
import { Markdown } from "./Markdown";

const PHASE_LABEL: Record<string, string> = {
  health_check: "Waking the model",
  mcp_tools: "Opening your studio tools",
  model: "Thinking",
};

function phaseLabel(phase: string | null): string {
  if (!phase) {
    return "Thinking";
  }
  return PHASE_LABEL[phase] ?? "Thinking";
}

function AssistantMessage() {
  const { thinkingPhase, offlineReply, sendMessage } = useStudio();
  const running = useAuiState((state) => state.message.status?.type === "running");
  const copied = useAuiState((state) => state.message.isCopied);
  const hasText = useAuiState((state) =>
    state.message.content.some((part) => part.type === "text" && part.text.trim().length > 0),
  );
  const error = useAuiState(
    (state) => state.message.metadata.custom?.error as StudioError | undefined,
  );
  const retryText = useAuiState(
    (state) => state.message.metadata.custom?.retryText as string | undefined,
  );

  return (
    // `aria-busy` keeps a screen reader from announcing every streamed token;
    // it reads the reply once the turn settles.
    <article className="message message--assistant" aria-busy={running}>
      <AssistantAvatar />
      <div className="message__body">
        {offlineReply ? <span className="message__tag">Local guidance</span> : null}

        <MessagePrimitive.Parts
          components={{
            Text: TextPart,
            Reasoning: ReasoningPart,
            Source: SourcePart,
            File: FilePart,
            data: { by_name: { [SURFACE_PART]: SurfacePart } },
            tools: { Fallback: ToolPart },
          }}
        />

        {running && !hasText ? <TypingPart label={phaseLabel(thinkingPhase)} /> : null}
        {running && hasText ? <span className="caret" aria-hidden="true" /> : null}

        {error ? (
          <FailurePanel
            error={error}
            retryText={retryText}
            onRetry={(text) => void sendMessage(text)}
          />
        ) : null}

        <AuiIf condition={(state) => state.message.branchCount > 1}>
          {/* The group carries the name. Putting an aria-label on the position
              text instead would replace "2 of 2" for screen readers with the
              label, hiding the one thing the control exists to state. */}
          <BranchPickerPrimitive.Root
            className="branch-picker"
            role="group"
            aria-label="Reply alternatives"
          >
            <BranchPickerPrimitive.Previous
              className="branch-picker__step"
              aria-label="Previous alternative"
            >
              ‹
            </BranchPickerPrimitive.Previous>
            <span className="branch-picker__label">
              Alternative <BranchPickerPrimitive.Number /> of <BranchPickerPrimitive.Count />
            </span>
            <BranchPickerPrimitive.Next
              className="branch-picker__step"
              aria-label="Next alternative"
            >
              ›
            </BranchPickerPrimitive.Next>
          </BranchPickerPrimitive.Root>
        </AuiIf>

        {!running ? (
          <ActionBarPrimitive.Root
            className="message__actions"
            role="group"
            aria-label="Reply actions"
            hideWhenRunning
          >
            <ActionBarPrimitive.Copy
              className="quiet-action"
              aria-label={copied ? "Reply copied" : "Copy reply"}
            >
              {copied ? <CheckIcon size={14} /> : <CopyIcon size={14} />}
              {copied ? "Copied" : "Copy"}
            </ActionBarPrimitive.Copy>
            <ActionBarPrimitive.Reload className="quiet-action" aria-label="Regenerate reply">
              Regenerate
            </ActionBarPrimitive.Reload>
          </ActionBarPrimitive.Root>
        ) : null}
      </div>
    </article>
  );
}

function UserMessage() {
  const copied = useAuiState((state) => state.message.isCopied);

  return (
    <article className="message message--user">
      <div className="message__bubble">
        <MessagePrimitive.Parts components={{ Text: TextPart }} />
      </div>
      <MessagePrimitive.Attachments>
        {({ attachment }) => {
          // The turn owns the id; the prepared copy (if this session still has
          // it) supplies the preview and size the composer showed.
          const ready = attachment.content
            ?.map((part) => (part.type === "file" ? preparedAttachmentById(part.data) : null))
            .find((candidate) => candidate !== null);
          const size = ready ? formatFileSize(ready.size) : "";

          return (
            <span className="attachment-chip">
              {ready?.dataUrl ? (
                <img className="attachment-chip__thumb" src={ready.dataUrl} alt="" />
              ) : null}
              <span className="attachment-chip__meta">
                <span className="attachment-chip__name">{attachment.name}</span>
                {size ? <span className="attachment-chip__size">{size}</span> : null}
              </span>
            </span>
          );
        }}
      </MessagePrimitive.Attachments>
      <ActionBarPrimitive.Root
        className="message__actions message__actions--user"
        role="group"
        aria-label="Message actions"
      >
        <ActionBarPrimitive.Edit className="quiet-action" aria-label="Edit message">
          Edit
        </ActionBarPrimitive.Edit>
        <ActionBarPrimitive.Copy
          className="quiet-action"
          aria-label={copied ? "Message copied" : "Copy message"}
        >
          {copied ? "Copied" : "Copy"}
        </ActionBarPrimitive.Copy>
      </ActionBarPrimitive.Root>
    </article>
  );
}

function SystemMessage() {
  return (
    <article className="message message--notice">
      <MessagePrimitive.Parts components={{ Text: TextPart }} />
    </article>
  );
}

/** Editing a message in place: same verb, same place, no second surface. */
function EditComposer() {
  return (
    <ComposerPrimitive.Root className="composer composer--edit">
      <ComposerPrimitive.Input
        className="composer__input"
        submitMode="enter"
        aria-label="Edit message"
      />
      <div className="composer__actions">
        <ComposerPrimitive.Cancel className="quiet-action">Cancel</ComposerPrimitive.Cancel>
        <ComposerPrimitive.Send className="composer__send composer__send--text" aria-label="Save edit">
          Save
        </ComposerPrimitive.Send>
      </div>
    </ComposerPrimitive.Root>
  );
}

export function Conversation() {
  const { sendMessage, streaming, thinkingPhase } = useStudio();

  return (
    <UiActionContext.Provider
      value={{ onIntent: (intent) => void sendMessage(intent), busy: streaming }}
    >
      {/* The phase lives outside the log: the streaming reply is `aria-busy`,
          and a status message inside it would not be announced until the
          answer finished — the one moment it is no longer useful. */}
      <p className="sr-only" role="status" aria-live="polite">
        {streaming ? phaseLabel(thinkingPhase) : ""}
      </p>
      <div className="conversation" role="log" aria-live="polite" aria-label="Conversation">
        <ThreadPrimitive.Messages
          components={{
            UserMessage,
            AssistantMessage,
            SystemMessage,
            EditComposer,
          }}
        />
      </div>
    </UiActionContext.Provider>
  );
}

export { Markdown };

/**
 * The thread composer.
 *
 * Bound to the assistant-ui composer runtime: attachments, send, and cancel are
 * the library's. The Studio's own additions — the slash palette, the connector
 * chips, and the model hint — sit on top of it and use the same markup as the
 * setup wizard's composer.
 */

import { ComposerPrimitive, useAui, useAuiState } from "@assistant-ui/react";
import { useEffect, useId, useMemo, useRef, useState } from "react";

import {
  ATTACHMENT_ACCEPT,
  MAX_ATTACHMENT_CHARS,
  MAX_IMAGE_BYTES,
  attachmentRejection,
  formatFileSize,
  isImageLike,
} from "../../assistant/attachments";
import { isSlashCommand, matchCommands, type StudioCommand } from "../../lib/commands";
import { useStudio } from "../../state/StudioContext";
import { ArrowUpIcon, PaperclipIcon, StopIcon } from "../icons";
import { CommandPalette, ComposerHint, ConnectorChips, paletteOpenFor } from "./composerParts";
import { ModelPicker } from "./ModelPicker";

const acceptedAttachmentTypes = ATTACHMENT_ACCEPT.split(",");
const acceptedTextExtensions = acceptedAttachmentTypes.filter((type) => type.startsWith("."));
const acceptedImageTypes = acceptedAttachmentTypes
  .filter((type) => type.startsWith("image/"))
  .map((type) => type.slice("image/".length).toUpperCase());
const ATTACHMENT_HELP = `Supported text files (${acceptedTextExtensions.join(", ")} and text/*) and images (${acceptedImageTypes.join(", ")}). Images up to ${Math.floor(MAX_IMAGE_BYTES / (1024 * 1024))} MB; text files up to ${MAX_ATTACHMENT_CHARS.toLocaleString()} characters.`;

/** The local preview for an image before it is ever sent. */
function AttachmentThumb({ file }: { file?: File }) {
  const url = useMemo(() => {
    if (!file || !isImageLike(file.type) || typeof URL.createObjectURL !== "function") {
      return null;
    }
    return URL.createObjectURL(file);
  }, [file]);

  useEffect(() => {
    return () => {
      if (url) {
        URL.revokeObjectURL(url);
      }
    };
  }, [url]);

  if (!url) {
    return null;
  }
  return <img className="attachment-chip__thumb" src={url} alt="" />;
}

function AttachmentRow() {
  const aui = useAui();
  const attachments = useAuiState((state) => state.composer.attachments);

  if (attachments.length === 0) {
    return null;
  }

  return (
    <div className="composer__attachments" role="list" aria-label="Attachments">
      {attachments.map((attachment, index) => {
        const size = formatFileSize(attachment.file?.size ?? 0);
        return (
          <span className="attachment-chip" role="listitem" key={attachment.id}>
            <AttachmentThumb file={attachment.file} />
            <span className="attachment-chip__meta">
              <span className="attachment-chip__name">{attachment.name}</span>
              {size ? <span className="attachment-chip__size">{size}</span> : null}
            </span>
            <button
              type="button"
              className="attachment-chip__remove"
              aria-label={`Remove ${attachment.name}`}
              onClick={() => void aui.composer.attachment({ index }).remove()}
            >
              ✕
            </button>
          </span>
        );
      })}
    </div>
  );
}

function ComposerBody({
  onCommand,
  onSlashCommand,
  onFiles,
  placeholder,
  autoFocus = false,
}: {
  onCommand: (command: StudioCommand) => void;
  onSlashCommand?: (text: string) => boolean;
  onFiles: (files: File[]) => void;
  placeholder?: string;
  autoFocus?: boolean;
}) {
  const aui = useAui();
  const { llmHealth } = useStudio();
  // A page can mount more than one composer, so every id and description needs
  // to be unique per instance rather than a fixed string in the document.
  const attachmentHelpId = useId();
  const inputId = useId();
  const paletteId = useId();
  const text = useAuiState((state) => state.composer.text);
  const running = useAuiState((state) => state.thread.isRunning);
  const [highlight, setHighlight] = useState(0);
  // Remember which draft was dismissed, so typing again re-opens the palette
  // without an effect that writes state on every keystroke.
  const [dismissedFor, setDismissedFor] = useState<string | null>(null);

  const offline = llmHealth.healthy === false;
  const matches = useMemo(() => (paletteOpenFor(text) ? matchCommands(text) : []), [text]);
  const open = paletteOpenFor(text) && dismissedFor !== text;
  const activeIndex = Math.min(highlight, Math.max(matches.length - 1, 0));
  const activeCommand = matches[activeIndex];

  function choose(command: StudioCommand) {
    aui.composer.setText("");
    setHighlight(0);
    setDismissedFor("");
    onCommand(command);
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (open) {
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        if (!matches.length) {
          return;
        }
        const delta = event.key === "ArrowDown" ? 1 : -1;
        setHighlight((index) => (index + delta + matches.length) % matches.length);
        return;
      }
      if ((event.key === "Enter" || event.key === "Tab") && activeCommand) {
        event.preventDefault();
        choose(activeCommand);
        return;
      }
      if (event.key === "Escape") {
        event.preventDefault();
        setDismissedFor(text);
        return;
      }
    }

    // A command typed straight through — palette closed or never opened — is
    // still a command, and must never be sent to the model as prose.
    if (
      event.key === "Enter" &&
      !event.shiftKey &&
      !event.nativeEvent.isComposing &&
      isSlashCommand(text) &&
      onSlashCommand
    ) {
      event.preventDefault();
      aui.composer.setText("");
      setDismissedFor("");
      onSlashCommand(text);
    }
  }

  return (
    <>
      <CommandPalette
        id={paletteId}
        open={open}
        matches={matches}
        activeIndex={activeIndex}
        onHover={setHighlight}
        onChoose={choose}
      />
      <ConnectorChips />
      <AttachmentRow />
      <div className="composer__shell">
        <label className="sr-only" htmlFor={inputId}>
          Message the studio
        </label>
        <ComposerPrimitive.Input
          id={inputId}
          className="composer__input"
          rows={1}
          autoFocus={autoFocus}
          placeholder={
            placeholder ??
            (offline
              ? "Model offline — type / for commands, or capture what you know…"
              : "What do you want to make happen?")
          }
          aria-autocomplete="list"
          aria-expanded={open}
          aria-controls={open ? paletteId : undefined}
          onKeyDown={onKeyDown}
          onPaste={(event) => {
            // A screenshot on the clipboard is a file, not text: attach it
            // rather than letting the browser paste a placeholder name.
            const files = Array.from(event.clipboardData?.files ?? []);
            if (files.length === 0) {
              return;
            }
            event.preventDefault();
            onFiles(files);
          }}
        />
        <div className="composer__actions">
          <ComposerPrimitive.AddAttachment
            className="composer__attach"
            aria-label="Attach a file"
            aria-describedby={attachmentHelpId}
            title={ATTACHMENT_HELP}
          >
            <PaperclipIcon size={16} />
          </ComposerPrimitive.AddAttachment>
          <span id={attachmentHelpId} className="sr-only">
            {ATTACHMENT_HELP}
          </span>
          {running ? (
            <ComposerPrimitive.Cancel
              className="composer__send composer__send--stop"
              aria-label="Stop generating"
            >
              <StopIcon size={16} />
            </ComposerPrimitive.Cancel>
          ) : (
            <ComposerPrimitive.Send className="composer__send" aria-label="Send message">
              <ArrowUpIcon size={18} />
            </ComposerPrimitive.Send>
          )}
        </div>
      </div>
      <ComposerHint trailing={<ModelPicker />} />
    </>
  );
}

function hasFiles(event: React.DragEvent<HTMLElement>): boolean {
  return Array.from(event.dataTransfer?.types ?? []).includes("Files");
}

export function ThreadComposer(props: {
  onCommand: (command: StudioCommand) => void;
  onSlashCommand?: (text: string) => boolean;
  placeholder?: string;
  autoFocus?: boolean;
}) {
  const aui = useAui();
  const { pushToast } = useStudio();
  const [dragging, setDragging] = useState(false);
  // dragenter/dragleave fire for every child; count depth so moving over the
  // textarea does not flicker the drop state off and on.
  const dragDepth = useRef(0);

  function attachFiles(files: File[]) {
    for (const file of files) {
      const rejection = attachmentRejection(file);
      if (rejection) {
        pushToast("error", rejection);
        continue;
      }
      void aui.composer.addAttachment(file);
    }
  }

  return (
    <ComposerPrimitive.Root
      className={`composer${dragging ? " is-dragging" : ""}`}
      onDragEnter={(event) => {
        if (!hasFiles(event)) {
          return;
        }
        event.preventDefault();
        dragDepth.current += 1;
        setDragging(true);
      }}
      onDragOver={(event) => {
        if (!hasFiles(event)) {
          return;
        }
        // Without this the browser opens the dropped file instead.
        event.preventDefault();
      }}
      onDragLeave={() => {
        // Leave events often carry no types, so this only ever removes depth we
        // added on a file drag.
        dragDepth.current = Math.max(dragDepth.current - 1, 0);
        if (dragDepth.current === 0) {
          setDragging(false);
        }
      }}
      onDrop={(event) => {
        if (!hasFiles(event)) {
          return;
        }
        event.preventDefault();
        dragDepth.current = 0;
        setDragging(false);
        attachFiles(Array.from(event.dataTransfer.files));
      }}
    >
      {dragging ? <p className="composer__drop-hint">Drop to attach</p> : null}
      <ComposerBody {...props} onFiles={attachFiles} />
    </ComposerPrimitive.Root>
  );
}

/**
 * Chrome shared by both composers.
 *
 * The thread composer is bound to the assistant-ui runtime (attachments, stop,
 * queueing); the setup wizard's composer is a controlled textarea because its
 * turns are local until the context is saved. The command palette, the
 * connector chips, and the hint row are the same in both, so they live here.
 */

import type { ReactNode } from "react";

import { isCommandDraft, type StudioCommand } from "../../lib/commands";
import { useStudio } from "../../state/StudioContext";

export function CommandPalette({
  id,
  open,
  matches,
  activeIndex,
  onHover,
  onChoose,
}: {
  /** Unique per composer: two composers can be mounted at once. */
  id: string;
  open: boolean;
  matches: StudioCommand[];
  activeIndex: number;
  onHover: (index: number) => void;
  onChoose: (command: StudioCommand) => void;
}) {
  if (!open) {
    return null;
  }

  return (
    <div className="palette" role="listbox" id={id} aria-label="Commands">
      {matches.length ? (
        matches.map((command, index) => (
          <button
            key={command.id}
            type="button"
            role="option"
            aria-selected={index === activeIndex}
            className={`palette__item${index === activeIndex ? " is-active" : ""}`}
            onMouseEnter={() => onHover(index)}
            onClick={() => onChoose(command)}
          >
            <code className="palette__name">{command.name}</code>
            <span className="palette__text">
              <span className="palette__label">{command.label}</span>
              <span className="palette__description">{command.description}</span>
            </span>
          </button>
        ))
      ) : (
        <p className="palette__empty">
          No command matches. Type <code>/help</code> for the full list.
        </p>
      )}
    </div>
  );
}

export function ConnectorChips() {
  const {
    connectorSuggestions,
    presets,
    dismissConnectorSuggestion,
    refreshConnectors,
  } = useStudio();

  if (connectorSuggestions.length === 0) {
    return null;
  }

  return (
    <div className="composer__suggestions" aria-label="Connector suggestions">
      {connectorSuggestions.map((id) => {
        const label = presets.find((preset) => preset.id === id)?.label ?? id;
        return (
          <button
            key={id}
            type="button"
            className="composer__suggestion"
            aria-label={`Added ${label}, dismiss`}
            onClick={() => {
              dismissConnectorSuggestion(id);
              void refreshConnectors();
            }}
          >
            <span>Added {label}</span>
            <span aria-hidden>✕</span>
          </button>
        );
      })}
    </div>
  );
}

export function ComposerHint({ trailing }: { trailing?: ReactNode } = {}) {
  const { settings, llmHealth, brief } = useStudio();
  const offline = llmHealth.healthy === false;

  return (
    <div className="composer__hint">
      <span>
        <kbd>Enter</kbd> to send · <kbd>/</kbd> for commands
        {brief ? ` · ${brief.product_name || "your job"}` : ""}
      </span>
      <span className="composer__hint-end">
        {offline ? <span className="composer__status is-offline">Local guidance</span> : null}
        {trailing ??
          (offline ? null : <span className="composer__status">{settings.model_name}</span>)}
      </span>
    </div>
  );
}

/** Whether a draft should open the command palette. */
export function paletteOpenFor(value: string): boolean {
  return isCommandDraft(value);
}

import { ThreadPrimitive, useThreadViewport } from "@assistant-ui/react";

import {
  HELP_TEXT,
  IMPACT_PROMPT,
  STUDIO_COMMANDS,
  isSlashCommand,
  type StudioCommand,
} from "../../lib/commands";
import { useMediaQuery } from "../../lib/useMediaQuery";
import { useStudio } from "../../state/StudioContext";
import type { WorkspacePanelId } from "../../types";
import { SetupConversation } from "../setup/SetupConversation";
import { Conversation } from "./Conversation";
import { Hero } from "./Hero";
import { OfflineNotice } from "./OfflineNotice";
import { ThreadComposer } from "./ThreadComposer";

const VIEW_COMMANDS = new Set<string>(["landscape", "jobmap", "evidence", "settings"]);

function LatestMessageButton() {
  const isAtBottom = useThreadViewport((state) => state.isAtBottom);
  const scrollToBottom = useThreadViewport((state) => state.scrollToBottom);
  // A reader who asked for less motion should land on the newest reply, not
  // watch the transcript animate past everything in between.
  const reducedMotion = useMediaQuery("(prefers-reduced-motion: reduce)");

  if (isAtBottom) {
    return null;
  }

  return (
    <button
      type="button"
      className="chat__latest"
      onClick={() => scrollToBottom({ behavior: reducedMotion ? "auto" : "smooth" })}
    >
      Latest message
    </button>
  );
}

export function ChatStage() {
  const {
    messages,
    sendMessage,
    pushNotice,
    openPanel,
    closePanel,
    clearChat,
    openSetup,
    setupOpen,
    canvas,
    brief,
    settings,
    mcpReachable,
    llmHealth,
  } = useStudio();

  const empty = messages.length === 0;

  function runCommand(command: StudioCommand) {
    if (VIEW_COMMANDS.has(command.id)) {
      openPanel(command.id as WorkspacePanelId);
      return;
    }
    switch (command.id) {
      case "help":
        pushNotice(HELP_TEXT);
        return;
      case "new":
      case "home":
        clearChat();
        closePanel();
        return;
      case "start":
        openSetup();
        return;
      case "jobs": {
        const jobs = canvas?.jobs ?? [];
        const lines = jobs.length
          ? jobs.map((job) => `- **${job.id}** — ${job.name ?? "Untitled job"}`)
          : ["- Nothing captured yet. Use `/start` to name the job."];
        pushNotice(
          [
            `**${jobs.length} job${jobs.length === 1 ? "" : "s"} on the canvas**`,
            ...lines,
            "",
            brief?.job_statement ? `Working job: ${brief.job_statement}` : "",
          ]
            .filter(Boolean)
            .join("\n"),
        );
        openPanel("jobmap");
        return;
      }
      case "impact":
        void sendMessage(IMPACT_PROMPT);
        return;
      case "capture":
        // With a model, capture is a sentence. Without one, the offline form
        // is the only honest path that still writes to the repository.
        if (llmHealth.healthy === false) {
          openPanel("capture");
          return;
        }
        void sendMessage(
          "I want to capture an outcome I heard from a customer. Ask me what they said.",
        );
        return;
      case "status":
        pushNotice(
          [
            "**Studio status**",
            `- Model: ${settings.model_name} at ${settings.base_url} — ${
              llmHealth.healthy === null
                ? "checking"
                : llmHealth.healthy
                  ? "reachable"
                  : "offline"
            }`,
            `- MCP: ${mcpReachable ? "connected" : "offline"} (${settings.mcp_url})`,
            `- Context: ${
              brief ? `${brief.product_name || "named job"} — ${brief.job_statement}` : "not set"
            }`,
            `- Canvas: ${canvas?.jobs.length ?? 0} jobs, ${canvas?.outcomes.length ?? 0} outcomes`,
          ].join("\n"),
        );
        return;
      default:
        return;
    }
  }

  function submitCommand(text: string) {
    if (!isSlashCommand(text)) {
      return false;
    }
    const token = text.split(/\s+/)[0].toLowerCase();
    const command = STUDIO_COMMANDS.find((entry) => entry.name === token);
    if (command) {
      runCommand(command);
    } else {
      pushNotice(`Unknown command: \`${token}\`. Type \`/help\` for the full list.`);
    }
    return true;
  }

  if (setupOpen) {
    return <SetupConversation />;
  }

  if (empty) {
    return (
      <section className="chat chat--empty" aria-label="Studio conversation">
        <OfflineNotice />
        <div className="chat__welcome">
          <div className="chat__welcome-inner">
            <Hero />
            <ThreadComposer
              onCommand={(command) => runCommand(command)}
              onSlashCommand={submitCommand}
              autoFocus
            />
          </div>
        </div>
      </section>
    );
  }

  return (
    <ThreadPrimitive.Root className="chat" aria-label="Studio conversation">
      <OfflineNotice />
      <div className="chat__transcript">
        <ThreadPrimitive.Viewport className="chat__scroll" autoScroll>
          <div className="chat__thread">
            <Conversation />
          </div>
        </ThreadPrimitive.Viewport>
        <LatestMessageButton />
      </div>
      <div className="chat__dock">
        <ThreadComposer
          onCommand={(command) => runCommand(command)}
          onSlashCommand={submitCommand}
        />
      </div>
    </ThreadPrimitive.Root>
  );
}

